3896:         cargo_case: Option<(&str, &str, i32)>,
3897:     ) -> WorkflowStepRun {
3898:         let root = crate::unique_temp_dir("cod108_workflow_step").unwrap();
3899:         let bin = root.join("bin");
3900:         fs::create_dir_all(&bin).unwrap();
3901:         let calls_path = root.join("calls");
3902:         fs::write(&calls_path, "").unwrap();
3903:         fs::create_dir_all(root.join("cod108")).unwrap();
3904:         let write_stub = |name: &str, header: &str, cases: &[(&str, &str, i32)]| {
3905:             let mut body = header.to_string();
3906:             for (index, (request, response, exit)) in cases.iter().enumerate() {
3907:                 let path = root.join(format!("{name}-response-{index}"));
3908:                 fs::write(&path, response.as_bytes()).unwrap();
3909:                 let _ = path;
3910:                 if request.contains(' ') {
3911:                     body.push_str(&format!(
3912:                         "  '{request}') cat \"$RUNNER_TEMP/{name}-response-{index}\"; exit {exit} ;;\n"
3913:                     ));
3914:                 } else {
3915:                     body.push_str(&format!(
3916:                         "  *{request}*) cat \"$RUNNER_TEMP/{name}-response-{index}\"; exit {exit} ;;\n"
3917:                     ));
3918:                 }
3919:             }
3920:             body.push_str(&format!(
3921:                 "  *) echo \"Unexpected {name} request: $*\" >&2; exit 97 ;;\nesac\n"
3922:             ));
3923:             let path = bin.join(name);
3924:             fs::write(&path, body).unwrap();
3925:             fs::set_permissions(&path, fs::Permissions::from_mode(0o755)).unwrap();
3926:         };
3927:         write_stub("gh", "#!/bin/bash\nset -euo pipefail\nprintf 'gh %s\\n' \"$*\" >> \"$RUNNER_TEMP/calls\"\ncase \"$*\" in\n", gh_cases);
3928:         write_stub("git", "#!/bin/bash\nset -euo pipefail\nprintf 'git %s\\n' \"$*\" >> \"$RUNNER_TEMP/calls\"\ncase \"$*\" in\n", git_cases);
3929:         if let Some((request, response, exit)) = cargo_case {
3930:             write_stub("cargo", "#!/bin/bash\nset -euo pipefail\nprintf 'cargo cwd=%s argv=%s\\n' \"$PWD\" \"$*\" >> \"$RUNNER_TEMP/calls\"\ncase \"$*\" in\n", &[ (request,response,exit) ]);
3931:         } else {
3932:             write_stub("cargo", "#!/bin/bash\nset -euo pipefail\nprintf 'cargo cwd=%s argv=%s\\n' \"$PWD\" \"$*\" >> \"$RUNNER_TEMP/calls\"\ncase \"$*\" in\n", &[]);
3933:         }
3934:         let workspace = root.join("workspace");
3935:         fs::create_dir_all(workspace.join("trusted-base/crates/xtask/src")).unwrap();
3936:         fs::create_dir_all(workspace.join("git-objects")).unwrap();
3937:         fs::write(
3938:             workspace.join("trusted-base/crates/xtask/src/ci.rs"),
3939:             b"fixture trusted classifier path",
3940:         )
3941:         .unwrap();
3942:         for (relative, contents) in files {
3943:             let path = root.join(relative);
3944:             fs::create_dir_all(path.parent().unwrap()).unwrap();
3945:             fs::write(path, contents).unwrap();
3946:         }
3947:         let events_path = root.join("event.json");
3948:         let event = envs
3949:             .iter()
3950:             .find(|(key, _)| *key == "GITHUB_EVENT_JSON")
3951:             .map(|(_, value)| *value)
3952:             .unwrap_or("{}");
3953:         fs::write(&events_path, event).unwrap();
3954:         let mut command = Command::new("bash");
3955:         command
3956:             .arg("-c")
3957:             .arg(script)
3958:             .current_dir(&workspace)
3959:             .env_clear()
3960:             .env(
3961:                 "PATH",
3962:                 std::env::join_paths(
3963:                     std::iter::once(bin.clone())
3964:                         .chain(std::env::split_paths(&std::env::var_os("PATH").unwrap())),
3965:                 )
3966:                 .unwrap(),
3967:             )
3968:             .env("RUNNER_TEMP", &root)
3969:             .env("GITHUB_EVENT_PATH", &events_path)
3970:             .env("GITHUB_OUTPUT", root.join("output"))
3971:             .env("GITHUB_STEP_SUMMARY", root.join("summary"))
3972:             .env("GITHUB_WORKSPACE", &workspace)
3973:             .env("GITHUB_REPOSITORY", "owner/repo")
3974:             .env("GITHUB_REPOSITORY_ID", "12345")
3975:             .env("REPOSITORY_ID", "12345")
3976:             .env("GITHUB_EVENT_NAME", "pull_request")
3977:             .env("GITHUB_SHA", CI_REQUIRED_SHA)
3978:             .env("GITHUB_REF", "refs/pull/124/merge")
3979:             .env("BASH_ENV", "")
3980:             .env("GH_TOKEN", "fixture-token");
3981:         for (key, value) in envs {
3982:             if *key != "GITHUB_EVENT_JSON" {
3983:                 command.env(key, value);
3984:             }
3985:         }
3986:         let output = command.output().unwrap();
3987:         let calls = fs::read_to_string(&calls_path).unwrap_or_default();
3988:         let stdout_files = [
3989:             "output",
3990:             "summary",
3991:             "cod108/decision.json",
3992:             "cod108/decision.next",
3993:             "cod108/pr.json",
3994:             "cod108/main.json",
3995:             "cod108/classifier.json",
3996:         ]
3997:         .into_iter()
3998:         .filter_map(|relative| {
3999:             fs::read(root.join(relative))
4000:                 .ok()
4001:                 .map(|bytes| (relative.to_string(), bytes))
4002:         })
4003:         .collect();
4004:         let _ = fs::remove_dir_all(root);
4005:         WorkflowStepRun {
4006:             output,
4007:             calls,
4008:             stdout_files,
4009:         }
4010:     }
