4046:     fn run_required_result(
4047:         run: &str,
4048:         results: &Value,
4049:         decision: &Value,
4050:         event_name: &str,
4051:         event: &Value,
4052:         github_ref: &str,
4053:         replies: &[ApiReply],
4054:     ) -> RequiredRun {
4055:         let root = super::unique_temp_dir("ci_required_body").unwrap();
4056:         let bin = root.join("bin");
4057:         fs::create_dir_all(&bin).unwrap();
4058:         fs::write(root.join("calls"), "").unwrap();
4059:         let mut gh = String::from("#!/bin/bash\nset -euo pipefail\nprintf '%s\\n' \"$*\" >> \"$RUNNER_TEMP/calls\"\ncase \"$*\" in\n");
4060:         for (index, reply) in replies.iter().enumerate() {
4061:             let response = root.join(format!("api-{index}.json"));
4062:             fs::write(&response, &reply.body).unwrap();
4063:             gh.push_str(&format!(
4064:                 "  {:?}) cat \"{}\"; exit {} ;;\n",
4065:                 reply.request,
4066:                 response.display(),
4067:                 reply.exit
4068:             ));
4069:         }
4070:         gh.push_str("  *) echo \"Unexpected GitHub request: $*\" >&2; exit 97 ;;\nesac\n");
4071:         fs::write(bin.join("gh"), gh).unwrap();
4072:         fs::set_permissions(bin.join("gh"), fs::Permissions::from_mode(0o755)).unwrap();
4073:         fs::write(root.join("event.json"), serde_json::to_vec(event).unwrap()).unwrap();
4074:         fs::write(root.join("summary"), "").unwrap();
4075:         let output = Command::new("bash")
4076:             .arg("-c")
4077:             .arg(run)
4078:             .current_dir(&root)
4079:             .env_clear()
4080:             .env(
4081:                 "PATH",
4082:                 std::env::join_paths(
4083:                     std::iter::once(bin)
4084:                         .chain(std::env::split_paths(&std::env::var_os("PATH").unwrap())),
4085:                 )
4086:                 .unwrap(),
4087:             )
4088:             .env("BASH_ENV", "")
4089:             .env("RESULTS", results.to_string())
4090:             .env("DECISION", decision.to_string())
4091:             .env("GITHUB_EVENT_NAME", event_name)
4092:             .env("GITHUB_REPOSITORY", "owner/repo")
4093:             .env(
4094:                 "GITHUB_SHA",
4095:                 decision["run_sha"].as_str().unwrap_or(CI_REQUIRED_SHA),
4096:             )
4097:             .env("GITHUB_REF", github_ref)
4098:             .env("GITHUB_EVENT_PATH", root.join("event.json"))
4099:             .env("REPOSITORY_ID", "12345")
4100:             .env("RUNNER_TEMP", &root)
4101:             .env("GITHUB_STEP_SUMMARY", root.join("summary"))
4102:             .env("GH_TOKEN", "fixture-token")
4103:             .output()
4104:             .unwrap();
4105:         let calls = fs::read_to_string(root.join("calls")).unwrap_or_default();
4106:         let summary = fs::read_to_string(root.join("summary")).unwrap_or_default();
4107:         fs::remove_dir_all(root).unwrap();
4108:         RequiredRun {
4109:             output,
4110:             calls,
4111:             summary,
4112:         }
4113:     }
